import { chromium } from '/opt/e2e-deps/node_modules/playwright/index.mjs';
const results = [];
const check = (name, ok, detail = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + detail : ''}`);
const T = (id) => `[data-testid="${id}"]`;
const settle = (p) => p.waitForTimeout(250);
const BASE = 'http://localhost:4200';
const browser = await chromium.launch({ executablePath: '/opt/ms-playwright/chromium-1234/chrome-linux/chrome', args: ['--no-sandbox'] });
const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
await page.clock.setFixedTime(new Date('2026-09-15T08:00:00'));

// Movie list: failure, loading, retry
let fail = true;
await page.route('**/movies', async (route) => (fail ? route.abort() : route.continue()));
await page.goto(BASE + '/');
await page.waitForSelector(T('movies-error'), { timeout: 20000 });
check('error text', (await page.locator(T('movies-error')).textContent()).trim() === 'Failed to load movies');
check('retry button', (await page.locator(T('movies-retry-button')).textContent()).trim() === 'Retry');
check('no cards on error', (await page.locator(T('movie-card')).count()) === 0);
fail = false;
await page.locator(T('movies-retry-button')).click();
await page.waitForSelector(T('movie-card'), { timeout: 20000 });
check('retry loads cards', (await page.locator(T('movie-card')).count()) === 5);
check('error gone after retry', (await page.locator(T('movies-error')).count()) === 0);

// Loading indicator while in flight
await page.route('**/screenings', async (route) => { await new Promise((r) => setTimeout(r, 1500)); return route.continue(); });
await page.goto(BASE + '/?date=2026-09-16');
await page.waitForSelector(T('movies-loading'), { timeout: 5000 });
check('loading text', (await page.locator(T('movies-loading')).textContent()).includes('Loading…'));
check('no cards while loading', (await page.locator(T('movie-card')).count()) === 0);
await page.waitForSelector(T('movie-card'), { timeout: 20000 });
check('loading gone', (await page.locator(T('movies-loading')).count()) === 0);
await page.unroute('**/screenings');

// Screening 404 -> redirect
await page.goto(BASE + '/screenings/999/seats');
await page.waitForURL(BASE + '/', { timeout: 15000 });
check('404 screening redirects', true);

// Summary without booking -> redirect
await page.goto(BASE + '/screenings/1/summary');
await page.waitForURL(BASE + '/', { timeout: 15000 });
check('summary without booking redirects', true);

// Build a booking for screening 2 (Tue 15 Sep 19:30), 2 seats
await page.goto(BASE + '/screenings/2/seats');
await page.waitForSelector(T('seat-map'));
await page.locator(`${T('seat')}[data-row="12"][data-column="5"]`).click(); await settle(page);
await page.locator(`${T('seat')}[data-row="12"][data-column="6"]`).click(); await settle(page);
check('selected 2', (await page.locator(T('selected-seats-count')).textContent()).trim() === 'Selected seats: 2');
// Hover does not change colour
const before = await page.locator(`${T('seat')}[data-row="12"][data-column="7"]`).evaluate((el) => getComputedStyle(el).backgroundColor);
await page.locator(`${T('seat')}[data-row="12"][data-column="7"]`).hover(); await settle(page);
const hovered = await page.locator(`${T('seat')}[data-row="12"][data-column="7"]`).evaluate((el) => getComputedStyle(el).backgroundColor);
check('hover keeps colour', before === hovered && before === 'rgb(46, 125, 50)', before + ' vs ' + hovered);
// Summary of booking shows selection in row 12 price 39
await page.locator(T('continue-button')).click(); await settle(page);
await page.waitForSelector(T('summary-list'));
check('summary price 39', (await page.locator(T('summary-item-price')).first().textContent()).trim() === '39.00 PLN');
// Summary: remove one, then remove last -> seat map
await page.locator(T('summary-item-remove-button')).first().click(); await settle(page);
check('after remove total 39', (await page.locator(T('summary-total')).textContent()).trim() === 'Total: 39.00 PLN');
await page.locator(T('summary-item-remove-button')).first().click();
await page.waitForURL(BASE + '/screenings/2/seats', { timeout: 15000 });
check('removing last returns to seat map', true);
await page.waitForSelector(T('seat-map'));
check('seat map after removal empty', (await page.locator(T('selected-seats-count')).textContent()).trim() === 'Selected seats: 0');
check('continue disabled with no seat', await page.locator(T('continue-button')).isDisabled());

// Select a couch in row 15 and go to checkout; then screening 1 discards it
await page.locator(`${T('couch')}[data-row="15"][data-column-start="7"]`).click(); await settle(page);
await page.locator(T('continue-button')).click(); await settle(page);
await page.waitForSelector(T('summary-list'));
check('couch price 89', (await page.locator(T('summary-item-price')).first().textContent()).trim() === '89.00 PLN');
check('couch seat text', (await page.locator(T('summary-item-seat')).first().textContent()).trim() === 'Couch 7-8');
await page.locator(T('confirm-button')).click(); await settle(page);
await page.waitForSelector(T('checkout-title'));
check('pay label 89', (await page.locator(T('pay-button')).textContent()).trim() === 'Pay 89.00 PLN');
await page.locator(T('first-name-input')).fill('Jan'); await settle(page);
await page.locator(T('last-name-input')).fill('Nowak'); await settle(page);
await page.locator(T('email-input')).fill('jan@example.com'); await settle(page);
await page.locator(T('confirm-email-input')).fill('jan@example.com'); await settle(page);
await page.locator(T('terms-checkbox')).locator('input').check(); await settle(page);

// Payment failure: abort POST
await page.route('**/reservations', (route) => route.abort());
await page.locator(T('pay-button')).click(); await settle(page);
await page.waitForSelector(T('toast'), { timeout: 10000 });
check('payment failed toast', (await page.locator(T('toast')).textContent()).trim() === 'Payment failed. Please try again.');
check('stays on checkout', page.url().endsWith('/screenings/2/checkout'));
check('pay enabled again', !(await page.locator(T('pay-button')).isDisabled()));
check('values kept after failure', (await page.locator(T('first-name-input')).inputValue()) === 'Jan');
await page.unroute('**/reservations');

// Processing state: delay POST
let releaseReq;
await page.route('**/reservations', async (route) => {
  await new Promise((r) => { releaseReq = r; });
  return route.continue();
});
await page.locator(T('pay-button')).click(); await settle(page);
check('processing text', (await page.locator(T('pay-button')).textContent()).trim() === 'Processing…');
check('pay disabled while in flight', await page.locator(T('pay-button')).isDisabled());
releaseReq();
await page.waitForURL(BASE + '/confirmation', { timeout: 15000 });
check('paid -> confirmation', true);
check('email on confirmation', (await page.locator(T('confirmation-message')).textContent()).trim() === 'Your tickets will be sent shortly to jan@example.com');
await page.unroute('**/reservations');

// Request body check: capture a new booking request
await page.locator(T('confirmation-continue-button')).click();
await page.waitForURL(BASE + '/');
// seat map for screening 1 is a new booking with no selection
await page.goto(BASE + '/screenings/1/seats');
await page.waitForSelector(T('seat-map'));
check('new booking empty', (await page.locator(T('selected-seats-count')).textContent()).trim() === 'Selected seats: 0');
check('no legacy selection couch', (await page.locator(`${T('couch')}[data-state="selected"]`).count()) === 0);
check('no page errors', errors.length === 0, errors.join(' | ').slice(0, 400));
console.log(results.join('\n'));
await browser.close();
EOF
